Q: Patchwork: how do I &quot;break the alignment&quot; of two plots with different aspect ratio within the same row? A: <p>One option is to leave {patchwork} behind and lay out the grobs yourself with {gridExtra}. Convert the ggplots with <code>ggplotGrob()</code> and the <code>gt</code> table with <code>gt::as_gtable()</code>, then assemble everything with <code>arrangeGrob() / grid.arrange()</code>. Also note the use of <code>grid</code> to draw the plot borders and add the tags.</p>
<pre class="lang-r prettyprint-override"><code>library(tidyr)
library(ggplot2)
library(gt)
library(grid)
library(gridExtra)
library(ggpubr)

border &lt;- theme(
  plot.background = element_blank(),
  panel.background = element_rect(
    color = &quot;#ff5000&quot;, linewidth = 2
  )
)
layout &lt;- matrix(
  c(1, NA, 2),
  nrow = 1, byrow = TRUE
)
gp_border &lt;- gpar(
  col = &quot;#808080&quot;, lwd = 1.5
)

# Convert to grobs
grobs &lt;- list(ex_tba, ex_pb, ex_pc, ex_pd) |&gt;
  lapply(
    \(x) {
      if (inherits(x, &quot;ggplot&quot;)) {
        (x + border) |&gt; ggplotGrob()
      } else if (inherits(x, &quot;gt_tbl&quot;)) {
        gt::as_gtable(x)
      }
    }
  )

# Add tag and plot border
grobs &lt;- Map(
  \(x, y) {
    grobTree(
      rectGrob(gp = gp_border),
      x,
      textGrob(
        label = letters[y],
        x = unit(0, &quot;npc&quot;) + unit(4, &quot;pt&quot;),
        y = unit(1, &quot;npc&quot;) - unit(4, &quot;pt&quot;),
        hjust = 0, vjust = 1,
        gp = gpar(fontface = &quot;bold&quot;, fontsize = 20)
      )
    )
  },
  grobs, seq_along(grobs)
)

row1 &lt;- arrangeGrob(
  grobs = grobs[1:2],
  widths = c(1, 0.1, 1.5),
  layout_matrix = layout
)
row2 &lt;- arrangeGrob(
  grobs = grobs[3:4],
  widths = c(1.5, 0.1, 1),
  layout_matrix = layout
)

patch &lt;- arrangeGrob(grobs = list(row1, row2), nrow = 2)

# Inner border around all 4 plots and the spacers
patch_bordered &lt;- grobTree(
  rectGrob(gp = gp_border),
  patch
)

# Add Frame around the whole patch
inner_pad &lt;- 5

framed &lt;- grobTree(
  # Border around the whole patch
  rectGrob(gp = gpar(
    col = &quot;#808080&quot;, lwd = 1.5
  )),
  # Patch, inset so it doesn't touch the frame
  grobTree(
    patch_bordered,
    vp = viewport(
      width  = unit(1, &quot;npc&quot;) - unit(2 * inner_pad, &quot;pt&quot;),
      height = unit(1, &quot;npc&quot;) - unit(2 * inner_pad, &quot;pt&quot;)
    )
  )
)

# Draw with some room around the frame
outer_space &lt;- 2

grid.arrange(
  grobTree(
    arrangeGrob(
      framed,
      top = &quot;linked&quot;
    ),
    vp = viewport(
      width  = unit(1, &quot;npc&quot;) - unit(2 * outer_space, &quot;pt&quot;),
      height = unit(1, &quot;npc&quot;) - unit(2 * outer_space, &quot;pt&quot;)
    )
  )
)
</code></pre>
